#include <vector>
#include <cmath>
#include <algorithm>
#include <queue>
#include <unordered_set>
using namespace std;

class Solution {
public:
    /**
     * 方法一：動態規劃（推薦）
     * 時間複雜度: O(n * sqrt(n))
     * 空間複雜度: O(n)
     */
    int numSquares(int n) {
        vector<int> dp(n + 1, INT_MAX);
        dp[0] = 0;

        // 預先計算完全平方數
        vector<int> squares;
        for (int i = 1; i * i <= n; i++) {
            squares.push_back(i * i);
        }

        // 填充 DP 表
        for (int i = 1; i <= n; i++) {
            for (int square : squares) {
                if (square > i) break;
                dp[i] = min(dp[i], dp[i - square] + 1);
            }
        }

        return dp[n];
    }

    /**
     * 方法二：BFS
     * 時間複雜度: O(n * sqrt(n))
     * 空間複雜度: O(n)
     */
    int numSquares_bfs(int n) {
        vector<int> squares;
        for (int i = 1; i * i <= n; i++) {
            squares.push_back(i * i);
        }

        queue<pair<int, int>> q;  // (remainder, level)
        q.push({n, 0});
        unordered_set<int> visited;
        visited.insert(n);

        while (!q.empty()) {
            auto [remainder, level] = q.front();
            q.pop();

            for (int square : squares) {
                int nextRemainder = remainder - square;

                if (nextRemainder == 0) {
                    return level + 1;
                }

                if (nextRemainder > 0 && visited.find(nextRemainder) == visited.end()) {
                    visited.insert(nextRemainder);
                    q.push({nextRemainder, level + 1});
                }
            }
        }

        return 0;
    }
};

