import java.util.*;

class Solution {
    /**
     * 方法一：動態規劃（推薦）
     * 時間複雜度: O(n * sqrt(n))
     * 空間複雜度: O(n)
     */
    public int numSquares(int n) {
        int[] dp = new int[n + 1];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;

        // 預先計算完全平方數
        List<Integer> squares = new ArrayList<>();
        for (int i = 1; i * i <= n; i++) {
            squares.add(i * i);
        }

        // 填充 DP 表
        for (int i = 1; i <= n; i++) {
            for (int square : squares) {
                if (square > i) break;
                dp[i] = Math.min(dp[i], dp[i - square] + 1);
            }
        }

        return dp[n];
    }

    /**
     * 方法二：BFS
     * 時間複雜度: O(n * sqrt(n))
     * 空間複雜度: O(n)
     */
    public int numSquares_bfs(int n) {
        List<Integer> squares = new ArrayList<>();
        for (int i = 1; i * i <= n; i++) {
            squares.add(i * i);
        }

        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{n, 0});  // [remainder, level]
        Set<Integer> visited = new HashSet<>();
        visited.add(n);

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int remainder = current[0];
            int level = current[1];

            for (int square : squares) {
                int nextRemainder = remainder - square;

                if (nextRemainder == 0) {
                    return level + 1;
                }

                if (nextRemainder > 0 && !visited.contains(nextRemainder)) {
                    visited.add(nextRemainder);
                    queue.offer(new int[]{nextRemainder, level + 1});
                }
            }
        }

        return 0;
    }
}

