// 完全背包 DP：dp[i] = 湊出 i 所需的最少完全平方數個數
// 時間複雜度: O(n√n)，空間複雜度: O(n)
int numSquares(int n) {
    int* dp = malloc(sizeof(int) * (n + 1));
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = i;                                   // 最差情況：全部用 1
        for (int j = 1; j * j <= i; j++) {
            if (dp[i - j * j] + 1 < dp[i]) dp[i] = dp[i - j * j] + 1;
        }
    }
    int ans = dp[n];
    free(dp);
    return ans;
}

